import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

@Controller('api/v1')
export class FnSfr029111X8af4cfController {
  @Get('/employee-departments')
  async listEmployeeDepartments(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '시스템 관리자');
    const query = checks.queryOf(req.query);

    const rawEmployeeId = query['employeeId'];
    let employeeId: string | null = null;
    if (rawEmployeeId !== undefined && rawEmployeeId !== null && rawEmployeeId !== '') {
      if (!/^\d+$/.test(String(rawEmployeeId))) {
        throw new ApiError(400, 'VALIDATION_FAILED', '임직원 값이 올바르지 않습니다.');
      }
      employeeId = String(rawEmployeeId);
    }

    const rawPage = query['page'];
    let pageNo = 0;
    if (rawPage !== undefined && rawPage !== null && rawPage !== '') {
      if (!/^\d+$/.test(String(rawPage))) {
        throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호가 올바르지 않습니다.');
      }
      pageNo = Number(rawPage);
    }

    const rawSize = query['size'];
    let size = DEFAULT_SIZE;
    if (rawSize !== undefined && rawSize !== null && rawSize !== '') {
      if (!/^\d+$/.test(String(rawSize)) || Number(rawSize) < 1) {
        throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기가 올바르지 않습니다.');
      }
      size = Math.min(Number(rawSize), MAX_SIZE);
    }

    return transaction(async (db) => {
      if (employeeId !== null) {
        const found = await db.query(
          'SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
          { employeeId },
        );
        if (found.length === 0) {
          throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '조회할 임직원을 찾을 수 없습니다.');
        }
      }

      const where = employeeId === null ? '' : 'WHERE employee_id = CAST(:employeeId AS bigint)';
      const filterParams: Record<string, unknown> = employeeId === null ? {} : { employeeId };

      const countRows = await db.query(
        'SELECT COUNT(*) AS "total" FROM employee_department ' + where,
        filterParams,
      );
      const total = Number(countRows[0]?.total ?? 0);

      const items = await db.query(
        'SELECT employee_department_id AS "employeeDepartmentId", '
          + 'employee_id AS "employeeId", '
          + 'department_id AS "departmentId", '
          + 'is_primary AS "isPrimary" '
          + 'FROM employee_department ' + where + ' '
          + 'ORDER BY employee_id, is_primary DESC, employee_department_id '
          + 'LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { ...filterParams, size, offset: pageNo * size },
      );

      return { items, page: pageNo, size, total };
    });
  }
}

