import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  Drawer,
  ErrorText,
  Field,
  Filters,
  LookupSelect,
  Pager,
  Pairs,
  RefName,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;

export default function FnSfr029111X8af4cfPage({ role, notify }: PageProps) {
  const [draftEmployeeId, setDraftEmployeeId] = useState<number | string>('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [pageNo, setPageNo] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);

  const { data, error, loading } = useData<Page>(
    () => call<Page>('GET', '/employee-departments', role, undefined, {
      employeeId,
      page: pageNo,
      size: SIZE,
    }),
    [role, employeeId, pageNo],
  );

  const items = data?.items ?? [];
  const hasPrimary = items.some((row) => row.isPrimary === true);
  // 가정: 주부서 정보가 없으면 첫 번째 소속 부서를 기본값으로 사용하고 경고를 표시한다.
  const primary = items.find((row) => row.isPrimary === true) ?? items[0];
  const employeeSelected = employeeId !== '';

  const search = () => {
    setPageNo(0);
    setEmployeeId(draftEmployeeId);
  };

  const reset = () => {
    setDraftEmployeeId('');
    setEmployeeId('');
    setPageNo(0);
  };

  return (
    <div className="bento">
      <section className="box span-8">
        <h2>겸직 소속</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="임직원">
            <LookupSelect
              table="employee"
              role={role}
              value={draftEmployeeId}
              onChange={setDraftEmployeeId}
              placeholder="전체"
            />
          </Field>
        </Filters>
        <Band total={data?.total} />
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          columns={[
            {
              key: 'employeeId',
              label: '임직원',
              render: (row) => <RefName table="employee" role={role} value={row.employeeId} />,
            },
            {
              key: 'departmentId',
              label: '부서',
              render: (row) => <RefName table="department" role={role} value={row.departmentId} />,
            },
            {
              key: 'isPrimary',
              label: '주부서 여부',
              render: (row) => <Badge value={row.isPrimary === true ? '주부서' : '겸직'} />,
            },
          ]}
          rows={items}
          onRowClick={setSelected}
          empty={loading ? '불러오는 중입니다.' : '조회된 소속이 없습니다.'}
        />
        <Pager
          page={data?.page ?? 0}
          size={data?.size ?? SIZE}
          total={data?.total ?? 0}
          onPage={setPageNo}
        />
      </section>
      <section className="box span-4">
        <h2>주부서</h2>
        {!employeeSelected ? (
          <p>임직원을 선택하면 주부서 기준 업무환경을 보여 줍니다.</p>
        ) : primary ? (
          <div>
            <Pairs
              items={[
                ['임직원', <RefName table="employee" role={role} value={primary.employeeId} />],
                ['기본 부서', <RefName table="department" role={role} value={primary.departmentId} />],
                ['겸직 부서 수', String(Math.max(items.length - 1, 0))],
              ]}
            />
            {!hasPrimary ? (
              <ErrorText text="주부서 정보가 없어 첫 번째 소속 부서를 기본값으로 사용합니다." />
            ) : null}
          </div>
        ) : (
          <p>소속 부서가 없습니다.</p>
        )}
      </section>
      {selected ? (
        <Drawer title="소속 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['임직원', <RefName table="employee" role={role} value={selected.employeeId} />],
              ['부서', <RefName table="department" role={role} value={selected.departmentId} />],
              ['주부서 여부', <Badge value={selected.isPrimary === true ? '주부서' : '겸직'} />],
            ]}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
